/// Every action with at least one key: the defaults, overridden by `[keybindings]`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Keymap {
    bindings: Vec<(Action, Vec<Key>)>,
}

impl Default for Keymap {
    fn default() -> Self {
        Self {
            bindings: ACTIONS.iter().map(|(action, _, keys)| (*action, keys.to_vec())).collect(),
        }
    }
}

/// The default keymap, for callers with no valid config.
pub fn default_keymap() -> &'static Keymap {
    static DEFAULT: LazyLock<Keymap> = LazyLock::new(Keymap::default);
    &DEFAULT
}

impl Keymap {
    /// Apply overrides to the defaults; a key bound twice is an error naming both actions.
    pub fn resolve(overrides: &[(Action, Vec<Key>)]) -> Result<Self, String> {
        let mut keymap = Self::default();
        for (action, keys) in overrides {
            if keys.is_empty() {
                return Err(format!("`{}` has no keys", action.name()));
            }
            let slot = keymap
                .bindings
                .iter_mut()
                .find(|(bound, _)| bound == action)
                .expect("every action listed");
            slot.1.clone_from(keys);
        }
        let mut seen: Vec<(Key, Action)> = Vec::new();
        for (action, keys) in &keymap.bindings {
            for &key in keys {
                match seen.iter().find(|(k, _)| *k == key) {
                    Some((_, first)) if first == action => {
                        return Err(format!(
                            "`{}` is bound twice to `{}`",
                            key.config_str(),
                            action.name()
                        ));
                    }
                    Some((_, first)) => {
                        return Err(format!(
                            "`{}` is bound to both `{}` and `{}`",
                            key.config_str(),
                            first.name(),
                            action.name()
                        ));
                    }
                    None => seen.push((key, *action)),
                }
            }
        }
        Ok(keymap)
    }

    /// Every action with its bound keys, in keymap-table order.
    #[cfg(test)]
    pub(crate) fn bindings(&self) -> &[(Action, Vec<Key>)] {
        &self.bindings
    }

    /// The action `key` fires, if any.
    #[must_use]
    pub fn action_for(&self, key: Key) -> Option<Action> {
        self.bindings.iter().find(|(_, keys)| keys.contains(&key)).map(|(action, _)| *action)
    }

    /// The action's hint key: the first bound key.
    #[must_use]
    pub fn hint(&self, action: Action) -> Key {
        self.bindings
            .iter()
            .find(|(bound, _)| *bound == action)
            .map(|(_, keys)| keys[0])
            .expect("every action bound")
    }
    app.settle_input();
    done
}

/// [`handle_key`]'s dispatch: the key's own action, its many early returns ahead of the tail.
fn dispatch_key(app: &mut App, key: KeyEvent, area: Rect, keymap: &Keymap) -> Result<()> {
    use crate::keymap::Action as K;
    use KeyCode::{Char, Down, Enter, Esc, Left, PageDown, PageUp, Right, Tab, Up};
    let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);

    // A keypress cancels the gesture but keeps consuming its drag events until mouse-up.
    app.cancel_divider_drag();
    // A key cancels a live gesture without copying, then does its own work.
    app.cancel_gesture();
    // Any keypress is the user doing something else: the settled highlight clears
    app.clear_settled_selection();

    if app.composing() {
        let alt = key.modifiers.contains(KeyModifiers::ALT);
        let alt_or_shift = key.modifiers.intersects(KeyModifiers::ALT | KeyModifiers::SHIFT);
        let word = alt || ctrl; // word-jump on Alt/Ctrl + arrow (terminal-dependent)
        // The wrapped width of the box, for vertical (wrapped-row) caret movement.
        let cw = ui::composer_content_width(ui::diff_inner_width(area, app));
        match key.code {
            Esc => app.cancel_comment(),
            // Alt/Shift+Enter (and Ctrl+J) insert a newline; plain Enter submits.
            Enter if alt_or_shift => app.input_push('\n'),
            Enter => app.submit_comment(),
            Char('j') if ctrl => app.input_push('\n'),
            // The box wraps, so `↑`/`↓` walk display rows here rather than editing text.
            Up => app.caret = ui::caret_vertical(&app.input, app.caret, cw, false),
            Down => app.caret = ui::caret_vertical(&app.input, app.caret, cw, true),
            code => apply_text_edit(app, code, ctrl, alt, word),
        }
        return Ok(());
    }

    // Search: the query edits like a draft; `tab` flips mode, page keys scroll the preview.
    if app.mode == Mode::Search {
        let alt = key.modifiers.contains(KeyModifiers::ALT);
        let word = alt || ctrl;
        match key.code {
            Esc => app.close_search(),
            Enter => app.search_open_pick()?,
            Tab => app.search_flip(),
            PageDown => app.scroll_search_preview(PAGE),
            PageUp => app.scroll_search_preview(-PAGE),
            // The single-line query has no rows, so `↑`/`↓` (and `ctrl+n`/`p`) move the pick.
            Down => app.search_move(1),
            Up => app.search_move(-1),
            Char('n') if ctrl => app.search_move(1),
            Char('p') if ctrl => app.search_move(-1),
            code => apply_text_edit(app, code, ctrl, alt, word),
        }
        return Ok(());
    }

    // Line field: digits or `$` type, the shared edits edit, Enter jumps, Esc closes.
    if app.line_open() {
        let alt = key.modifiers.contains(KeyModifiers::ALT);
        match key.code {
            Esc => app.close_find(),
            Enter => app.line_go(),
            Char(c @ ('0'..='9' | '$')) if !ctrl && !alt => app.line_type(c),
            code => {
                edit_command(app, code, ctrl, alt, alt || ctrl);
            }
        }

    let mut it = rest.chars();
    match (it.next(), it.next()) {
        (Some(ch), None)
            if !ch.is_whitespace()
                && unicode_width::UnicodeWidthChar::width(ch).unwrap_or(0) > 0 =>
        {
            Some(crate::keymap::Key { ctrl, alt, code: KeyCode::Char(ch) })
        }
        _ => None,
    }
}

/// Parse the `[keybindings]` table: each action name to a non-empty array of keys.
fn parse_keybindings(
    path: &Path,
    value: &toml::Value,
) -> Result<crate::keymap::Keymap, PluginConfigError> {
    use crate::keymap::{Action, Keymap};
    let Some(entries) = value.as_table() else {
        return Err(value_error(path, value, "keybindings", "a table of action bindings"));
    };
    let mut overrides = Vec::with_capacity(entries.len());
    let mut names_by_action = Vec::with_capacity(entries.len());
    // Loop-invariant, and this parse runs per frame (`CFG-*` snapshots): build it once.
    let expected = format!(
        "a non-empty array of keys, each a character or a named key ({}), alone or behind ctrl+/alt+",
        crate::keymap::KeyCode::names().collect::<Vec<_>>().join(", ")
    );
    for (name, keys) in entries {
        let Some(action) = Action::by_config_name(name) else {
            return Err(unknown_key_error(
                path,
                &format!("keybindings.{name}"),
                &Action::names().collect::<Vec<_>>().join(", "),
            ));
        };
        if let Some((_, first_name)) =
            names_by_action.iter().find(|(bound, _): &&(Action, &str)| *bound == action)
        {
            return Err(PluginConfigError::new(
                path,
                format!(
                    "invalid value for `keybindings`: `{first_name}` and `{name}` name the same action"
                ),
            ));
        }
        names_by_action.push((action, name.as_str()));
        let entry_key = format!("keybindings.{name}");
        let expected = expected.as_str();
        let Some(values) = keys.as_array() else {
            return Err(value_error(path, keys, &entry_key, expected));
github_cli = "op plugin run -- gh"

[keybindings]
up = ["ctrl+p", "k", "up"]
down = ["ctrl+n", "j", "down"]
delete = ["ctrl+h", "d"]

    }
}

/// The caret moves and deletes every text field shares, readline's; `false` when `code` is none.
fn edit_command(app: &mut App, code: KeyCode, ctrl: bool, alt: bool, word: bool) -> bool {
