/// One bound key: a [`KeyCode`], alone or under `ctrl` or `alt`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Key {
    pub ctrl: bool,
    pub alt: bool,
    pub code: KeyCode,
}

impl Key {
    /// A bare character, no modifier.
    pub const fn plain(ch: char) -> Self {
        Self { ctrl: false, alt: false, code: KeyCode::Char(ch) }
    }

    /// A `ctrl+<ch>` chord.
    pub const fn ctrl(ch: char) -> Self {
        Self { ctrl: true, alt: false, code: KeyCode::Char(ch) }
    }

    /// A bare named key, no modifier.
    pub const fn named(code: KeyCode) -> Self {
        Self { ctrl: false, alt: false, code }
    }

    /// The `ctrl+`/`alt+` prefixing both spellings share.
    fn prefixed(self, base: String) -> String {
        match (self.ctrl, self.alt) {
            (true, _) => format!("ctrl+{base}"),
            (false, true) => format!("alt+{base}"),
            (false, false) => base,
        }
    }

    /// The config spelling (`ctrl+f`, `pageup`); no `Display`, so callers pick this or `label`.
    pub fn config_str(self) -> String {
        self.prefixed(self.code.name())
    }

    /// The painted hint: the config spelling, a named key as its label (`→`, `PageUp`).
    pub fn label(self) -> String {
        self.prefixed(self.code.label())
    }
}

/// Every action with its config name and default keys, the one table the keymap derives from.
const ACTIONS: [(Action, &str, &[Key]); 48] = [
    (Action::Down, "down", &[Key::plain('j'), Key::named(KeyCode::Down)]),
    (Action::Up, "up", &[Key::plain('k'), Key::named(KeyCode::Up)]),
    (Action::NextHunk, "next-hunk", &[Key::plain(']')]),
    (Action::PrevHunk, "prev-hunk", &[Key::plain('[')]),

    }
}

/// The caret moves and deletes every text field shares, readline's; `false` when `code` is none.
fn edit_command(app: &mut App, code: KeyCode, ctrl: bool, alt: bool, word: bool) -> bool {
    use KeyCode::{Backspace, Char, Delete, End, Home, Left, Right};
    match code {
        Char('h') if ctrl => app.input_backspace(),
        Char('w') if ctrl => app.input_delete_word(),
        Char('a') if ctrl => app.caret_home(),
        Char('e') if ctrl => app.caret_end(),
        Char('u') if ctrl => app.input_kill_to_start(),
        Char('k') if ctrl => app.input_kill_to_end(),
        // `Alt+b`/`Alt+f` survive multiplexers that strip modified arrows.
        Char('b') if alt => app.caret_word_left(),
        Char('f') if alt => app.caret_word_right(),
        Char('d') | Delete if alt => app.input_delete_word_forward(),
        Left if word => app.caret_word_left(),
        Right if word => app.caret_word_right(),
        Left => app.caret_left(),
        Right => app.caret_right(),
        Home => app.caret_home(),
        End => app.caret_end(),
        Backspace if alt => app.input_delete_word(),
        Delete => app.input_delete_forward(),
        Backspace => app.input_backspace(),
        _ => return false,
    }
    true
}

